import{_ as t,o as c,c as o,a1 as d}from"./chunks/framework.BKrM4vFX.js";const m=JSON.parse('{"title":"Как участвовать в mock-services","description":"Как внести вклад в mock-services AXIIOM: настройка окружения, требования к изменениям, запуск проверок и подготовка pull request.","frontmatter":{"sourcePath":"CONTRIBUTING.md"},"headers":[{"level":1,"title":"Как участвовать в mock-services","slug":"Как-участвовать-в-mock-services","link":"#Как-участвовать-в-mock-services","children":[{"level":2,"title":"Чем можно помочь","slug":"Чем-можно-помочь","link":"#Чем-можно-помочь","children":[]},{"level":2,"title":"Правила для кода","slug":"Правила-для-кода","link":"#Правила-для-кода","children":[]},{"level":2,"title":"Как добавить нового провайдера (адаптер)","slug":"Как-добавить-нового-провайдера-адаптер","link":"#Как-добавить-нового-провайдера-адаптер","children":[]},{"level":2,"title":"Гайды интеграции: шаблон","slug":"Гайды-интеграции-шаблон","link":"#Гайды-интеграции-шаблон","children":[]},{"level":2,"title":"Процесс","slug":"Процесс","link":"#Процесс","children":[]},{"level":2,"title":"Обновление базового образа (security patches)","slug":"Обновление-базового-образа-security-patches","link":"#Обновление-базового-образа-security-patches","children":[]},{"level":2,"title":"Лицензия вкладов","slug":"Лицензия-вкладов","link":"#Лицензия-вкладов","children":[]}]}],"relativePath":"CONTRIBUTING.md","filePath":"CONTRIBUTING.md"}'),i={name:"CONTRIBUTING.md"};function s(a,e,l,r,n,p){return c(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="Как-участвовать-в-mock-services" tabindex="-1">Как участвовать в mock-services <a class="header-anchor" href="#Как-участвовать-в-mock-services" aria-label="Permalink to &quot;Как участвовать в mock-services&quot;">​</a></h1><p>Спасибо за интерес! Проект — моки банков и облачных касс по их официальным протоколам. Цель — дать интегратору рабочий, честный и объясняющий ошибки стенд <strong>до</strong> договора с провайдером.</p><p>Если вы ИИ-агент (Arena Agent Mode, Claude Code и т.п.), начните с <a href="./AGENTS"><code>AGENTS.md</code></a>: там обязательные прогоны, требования к шапкам, правилу «env в пяти местах» и к описанию PR. Планирование доработок и статусы задач — внутренний бриф проекта[^brief], подготовка к глубокому аудиту — внутренний пакет подготовки к аудиту[^audit-prep]. Документы лежат в закрытом репозитории команды <code>mock-services-docs</code> и в публичной документации не дублируются.</p><h2 id="Чем-можно-помочь" tabindex="-1">Чем можно помочь <a class="header-anchor" href="#Чем-можно-помочь" aria-label="Permalink to &quot;Чем можно помочь&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Тип вклада</th><th>Как</th></tr></thead><tbody><tr><td>Дефект мока</td><td>Issue с шаблоном «дефект мока»: что сделали, что ожидали, что получили, версия/коммит, <code>curl</code>-воспроизведение</td></tr><tr><td>Расхождение с протоколом провайдера</td><td>Issue с шаблоном «расхождение с протоколом»: ссылка на официальный раздел доки (или скриншот с датой), поле, ожидаемое поведение</td></tr><tr><td>Новый провайдер</td><td>Issue-предложение: название, публичная документация API, есть ли у вас доступ к тестовому контуру</td></tr><tr><td>Код</td><td>PR по правилам ниже</td></tr><tr><td>Документация</td><td>PR в <code>docs/integration/*</code>; конспекты провайдеров — в приватном <code>mock-services-docs</code> (доступ у мейнтейнеров)</td></tr></tbody></table><h2 id="Правила-для-кода" tabindex="-1">Правила для кода <a class="header-anchor" href="#Правила-для-кода" aria-label="Permalink to &quot;Правила для кода&quot;">​</a></h2><ol><li><strong>Zero dependencies.</strong> Ядро и адаптеры работают на одном Node (&gt;= 18) без npm-пакетов. Новые зависимости обсуждаются отдельно и почти всегда отклоняются.</li><li><strong>Фиделити важнее удобства.</strong> Если провайдер отклоняет запрос — мок тоже отклоняет, с тем же (или документированным) кодом. «Удобные» отступления допустимы только за флагом конфигурации и с пометкой в README.</li><li><strong>Ошибка = DX.</strong> Любой отказ: код + человекочитаемое объяснение + поле + подсказка + ссылка на официальный раздел доки (<code>core.createErrorCatalog</code>). Голые <code>400/500</code> без объяснения не принимаются.</li><li><strong>Тесты обязательны.</strong> <code>npm test</code> должен быть зелёным; на новый сценарий — новый пункт в selftest соответствующего сервиса; на дефект — регресс-тест.</li><li><strong>Тесты не должны быть флаки.</strong> Не опирайтесь на <code>sleep</code>, если можно дождаться события/состояния; используйте свободные порты (<code>:0</code>).</li><li><strong>Секреты и реальные данные запрещены.</strong> Только фейковые креды и тестовые карты; персональные данные покупателей в примерах не использовать.</li><li><strong>Стиль:</strong> 2 пробела, одинарные кавычки, <code>&#39;use strict&#39;;</code>, модули CommonJS; комментарии — по делу, на русском с английскими терминами (как в репозитории).</li></ol><h2 id="Как-добавить-нового-провайдера-адаптер" tabindex="-1">Как добавить нового провайдера (адаптер) <a class="header-anchor" href="#Как-добавить-нового-провайдера-адаптер" aria-label="Permalink to &quot;Как добавить нового провайдера (адаптер)&quot;">​</a></h2><ol><li><p>Создайте <code>services/&lt;provider&gt;-mock/server.js</code> на <code>packages/core</code> (образец — <code>services/tbank-mock</code>, <code>services/kassa-mock</code>).</p></li><li><p>Опишите в адаптере <strong>только протокол</strong>: маршруты, поля, коды ошибок, машину состояний, тестовые реквизиты. Инфраструктура — из ядра.</p></li><li><p>Заведите конспект провайдера в приватном репозитории <code>mock-services-docs</code> (каталог <code>&lt;provider&gt;/</code> — как у существующих адаптеров, например конспект Т-Банка): таблица «эндпоинт → официальный раздел доки → дата сверки → статус сверки». Пример заголовка конспекта:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># MyBank · Payment API — сверка с моком</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Эндпоинт мока | Официальный раздел доки | Дата сверки | Статус |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`POST /v2/Init\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> | https://developer.mybank.example/api/init | 2026-10-11 | сверено |</span></span></code></pre></div><p>Относительные ссылки между доками проверяются автоматически (<code>npm run check:links</code> входит в <code>npm test</code>) — битые ссылки CI не пропустит.</p></li><li><p>Напишите <code>services/&lt;provider&gt;-mock/selftest.js</code> со всеми сценариями контракта (успех, отказ, таймаут, дубли, отмена/возврат — по специфике провайдера).</p></li><li><p>Добавьте инструкцию «интеграция за 10 минут» в <code>docs/integration/&lt;provider&gt;.md</code> по шаблону ниже (минимальный набор разделов проверяет <code>npm run check:site</code>) и запись в таблицу README.</p></li><li><p>Внесите новый документ в навигацию сайта — <a href="https://github.com/rucorp/mock-services/blob/main/_sidebar.md" target="_blank" rel="noreferrer"><code>_sidebar.md</code></a> (и, если он описывает провайдера, в таблицу <a href="./docs/overview">карты документации</a>). Полноту навигации, слаги ссылок и самодостаточность сайта проверяет <code>npm run check:site</code> — он также входит в <code>npm test</code>.</p></li></ol><h2 id="Гайды-интеграции-шаблон" tabindex="-1">Гайды интеграции: шаблон <a class="header-anchor" href="#Гайды-интеграции-шаблон" aria-label="Permalink to &quot;Гайды интеграции: шаблон&quot;">​</a></h2><p>Гайд <code>docs/integration/&lt;provider&gt;.md</code> — «интеграция за 10 минут»: от запуска стенда до первого успешного платежа или чека. Шаблон один для всех адаптеров, чтобы гайды не расходились по структуре:</p><table tabindex="0"><thead><tr><th>№</th><th>Раздел</th><th>Что внутри</th></tr></thead><tbody><tr><td>—</td><td>Шапка</td><td>провайдер, ссылка на официальную документацию и дата сверки, предупреждения «не drop-in»</td></tr><tr><td>1</td><td>Запустить</td><td><code>docker compose up &lt;service&gt;</code> / <code>npm run start:&lt;service&gt;</code>, порт, синтетические креды стенда</td></tr><tr><td>2</td><td>Базовый флоу</td><td>curl-цепочка <code>Init</code>/<code>getToken</code> → форма/<code>PaymentURL</code> → серверная сверка статуса</td></tr><tr><td>3</td><td>Что мок проверяет за вас</td><td>валидация, подпись/checksum, суммы, статусные переходы, ошибки с <code>field</code>/<code>hint</code>/<code>doc</code></td></tr><tr><td>4</td><td>Негативные сценарии</td><td><code>X-Mock-Scenario</code>, тестовые карты, конвенции <code>fail-</code>/<code>hang-</code></td></tr><tr><td>5</td><td>Вебхуки</td><td>формат и подпись (или явное «подписи нет»), ACK, retry, SSRF-политика</td></tr><tr><td>6</td><td>Песочницы и часы</td><td><code>/mock/time</code>, <code>X-Mock-Sandbox</code>, <code>/mock/*</code>, <code>/admin</code></td></tr><tr><td>7</td><td>Известные отличия от боевого провайдера</td><td>список пометок <code>[VERIFY]</code>/<code>[FORK]</code> и ссылка на README сервиса, где они собраны</td></tr><tr><td>8</td><td>Ссылки</td><td>контракт (<code>services/&lt;provider&gt;-mock/README.md</code>), OpenAPI, <code>protocols/&lt;provider&gt;.json</code>, ядро</td></tr></tbody></table><p>Разделы нумеруются <code>## N.</code> подряд, без пропусков и дублей; разделы 4–7 допустимо объединять, если провайдер их не различает (например, read-only адаптер без вебхуков), но разделы 3 и 8 обязательны.</p><p>Обязательный минимум проверяет <code>npm run check:site</code> (входит в <code>npm test</code>): нумерация разделов 1..N, раздел «Что мок проверяет за вас» (или «Известные отличия …»), раздел «Ссылки» и ссылка на README сервиса. Все гайды в <code>docs/integration/</code> описывают протокол провайдера и следуют шаблону без исключений.</p><h2 id="Процесс" tabindex="-1">Процесс <a class="header-anchor" href="#Процесс" aria-label="Permalink to &quot;Процесс&quot;">​</a></h2><ol><li>Fork → ветка с говорящим именем (<code>fix/kassa-receipt-datetime</code>).</li><li><code>npm test</code> локально.</li><li>PR: что изменилось, зачем, как проверяли, ссылки на доку/issue.</li><li>Реагируйте на ревью; CI (Node 18/20/22 + docker smoke) должен быть зелёным.</li></ol><h2 id="Обновление-базового-образа-security-patches" tabindex="-1">Обновление базового образа (security patches) <a class="header-anchor" href="#Обновление-базового-образа-security-patches" aria-label="Permalink to &quot;Обновление базового образа (security patches)&quot;">​</a></h2><p>Базовый образ и релизный образ закреплены дайджестами (F-37), чтобы повторная сборка одной версии репозитория не получала другой base image. Обновляют пины <strong>только</strong> отдельным PR с обоснованием (CVE/плановое обновление):</p><ol><li>Новый дайджест <code>node:22-alpine</code>: <code>docker buildx imagetools inspect node:22-alpine --format &#39;{{json .Manifest.Digest}}&#39;</code> (или строка «Digest» на hub.docker.com/_/node для тега <code>22-alpine</code>).</li><li>Обновите <code>FROM node:22-alpine@sha256:…</code> в <code>Dockerfile</code> и запишите в PR дату и причину обновления.</li><li>Прогоните оба контура проверок: <code>npm test</code> и <code>node scripts/docker-smoke.js</code> (tbank-mock и kassa-mock обязаны стать <code>healthy</code>, persist/restore — работать при <code>--read-only</code>).</li><li>После публикации GHCR-образа обновите дайджест релиза в <code>docker-compose.include.yml</code> (<code>MOCK_IMAGE_DIGEST</code>, строка «Digest» на странице пакета <code>ghcr.io/rucorp/mock-services</code>) — это deployment artifact потребителей.</li></ol><h2 id="Лицензия-вкладов" tabindex="-1">Лицензия вкладов <a class="header-anchor" href="#Лицензия-вкладов" aria-label="Permalink to &quot;Лицензия вкладов&quot;">​</a></h2><p>Отправляя PR, вы соглашаетесь на распространение вклада под Apache-2.0 (см. <code>LICENSE</code>) и подтверждаете, что имеете право его предоставить.</p><p>[^brief]: <code>docs/briefs/CLAUDE-2026-10-12-agent-brief.md</code> — бриф доработок, статусы задач и волны. [^audit-prep]: <code>docs/audit/AUDIT-PREP-2026-10-12.md</code> — пакет подготовки к глубокому аудиту, карта покрытия.</p>`,23)])])}const k=t(i,[["render",s]]);export{m as __pageData,k as default};
